<?php require 'config/onesignal.php'; $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, 'https://api.onesignal.com/notifications'); curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/json; charset=utf-8', 'Authorization: Key ' . trim(ONESIGNAL_REST_API_KEY))); curl_setopt($ch, CURLOPT_RETURNTRANSFER, TRUE); curl_setopt($ch, CURLOPT_POST, TRUE); curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(['app_id'=>trim(ONESIGNAL_APP_ID), 'included_segments'=>['Total Subscriptions'], 'contents'=>['en'=>'Test']])); echo curl_exec($ch); ?>
